132	func applySet(items []queryItem, present bool, name, value string) (bool, []queryItem) {
133		encoded := encodeQueryComponent(name) + "=" + encodeQueryComponent(value)
134		first := firstNameHit(items, name)
135		if first < 0 {
136			items = append(items, queryItem{name: name, raw: encoded})
137			return true, items
138		}
139		// The merged pair takes the first hit's place; every later duplicate is
140		// dropped by the same keep-the-rest rule remove uses.
141		items[first].raw = encoded
142		return true, append(items[:first+1], dropName(items[first+1:], name)...)
143	}
