// applyCopy duplicates every parameter whose decoded name equals name: each
// copy keeps its source's position by following it immediately, carries the
// source's '=' and raw value bytes verbatim (a valueless source yields a
// valueless copy), and encodes only the new name the way set does. The
// originals stay in place, parameters already named to are left alone (never
// merged or overwritten), and copies made by this rule are not themselves
// re-copied. When nothing matches, or name and to are identical, every
// fragment keeps its bytes.
func applyCopy(items []queryItem, name, to string) []queryItem {
	if name == to {
		return items
	}
	encodedTo := encodeQueryComponent(to)
	out := make([]queryItem, 0, len(items))
	for _, it := range items {
		out = append(out, it)
		if !matchesName(it, name) {
			continue
		}
		frag := it.raw
		if j := strings.IndexByte(frag, '='); j >= 0 {
			frag = encodedTo + frag[j:]
		} else {
			frag = encodedTo
		}
		out = append(out, queryItem{name: to, raw: frag})
	}
	return out
}
